<?php
require __DIR__.'/includes/bootstrap.php';
require_permission('tasks.view');
$pdo=db();
$status=trim((string)($_GET['status']??''));
$where='1=1';$params=[];
if($status!==''){$where='t.status=?';$params[]=$status;}
$q=$pdo->prepare("SELECT t.*,e.full_name assignee,c.name category FROM tasks t LEFT JOIN employees e ON e.id=t.primary_assignee_id LEFT JOIN task_categories c ON c.id=t.category_id WHERE $where ORDER BY FIELD(t.status,'in_progress','in_review','to_do','blocked','backlog','completed','cancelled'),FIELD(t.priority,'urgent','high','medium','low'),COALESCE(t.due_at,'2999-12-31'),t.id DESC");
$q->execute($params);$tasks=$q->fetchAll();
$employees=$pdo->query("SELECT id,user_id,full_name FROM employees WHERE employment_status='active' ORDER BY full_name")->fetchAll();
$categories=$pdo->query('SELECT * FROM task_categories WHERE is_active=1 ORDER BY name')->fetchAll();
$workflow=['backlog'=>'Backlog','to_do'=>'To Do','in_progress'=>'In Progress','blocked'=>'Blocked','in_review'=>'In Review','completed'=>'Completed'];
$taskStats=[
 'total'=>count(array_filter($tasks,fn($t)=>$t['status']!=='cancelled')),
 'open'=>count(array_filter($tasks,fn($t)=>!in_array($t['status'],['completed','cancelled'],true))),
 'completed'=>count(array_filter($tasks,fn($t)=>$t['status']==='completed')),
 'overdue'=>count(array_filter($tasks,fn($t)=>$t['due_at']&&strtotime($t['due_at'])<time()&&!in_array($t['status'],['completed','cancelled'],true)))
];
$title='Task Management';$active='tasks';include __DIR__.'/includes/header.php';
?>
<section class="section-toolbar reveal"><div><p class="eyebrow">Execution workspace</p><h2>Kanban task workflow</h2><p class="muted">Create individual or team-wide tasks, duplicate responsibilities, and drag cards between workflow stages. Every move is saved to the database and audit history.</p></div><div class="toolbar-actions"><?php if(can('tasks.create')):?><button class="btn btn-primary" data-modal-open="taskModal" id="new-task"><i data-lucide="plus"></i>Add task</button><?php endif;?></div></section>
<section class="task-stat-strip reveal stagger-1"><div><span>Total active tasks</span><strong><?=number_format($taskStats['total'])?></strong></div><div><span>Open</span><strong><?=number_format($taskStats['open'])?></strong></div><div><span>Completed</span><strong><?=number_format($taskStats['completed'])?></strong></div><div class="danger-score"><span>Overdue</span><strong><?=number_format($taskStats['overdue'])?></strong></div></section>
<section class="kanban-helper reveal stagger-1"><div><i data-lucide="grip-vertical"></i><div><strong>Drag & drop workflow</strong><span>Move an authorized task directly between Backlog, To Do, In Progress, Blocked, In Review, and Completed.</span></div></div><div class="kanban-helper-chip"><i data-lucide="users-round"></i>Assign to all creates one independent copy per employee</div></section>
<section class="task-board kanban-pro reveal stagger-2" id="taskKanban" data-can-drag="<?=can('tasks.edit')?'1':'0'?>">
<?php foreach($workflow as $key=>$label):$list=array_values(array_filter($tasks,fn($t)=>$t['status']===$key));?>
<div class="task-column" data-task-column="<?=e($key)?>"><div class="column-head"><div><span><?=$label?></span><small><?=match($key){'backlog'=>'Queued for later','to_do'=>'Ready to start','in_progress'=>'Currently active','blocked'=>'Needs attention','in_review'=>'Awaiting review','completed'=>'Finished work',default=>''}?></small></div><b data-column-count><?=count($list)?></b></div><div class="task-stack" data-task-dropzone="<?=e($key)?>"><?php if(!$list):?><div class="column-empty" data-column-empty><i data-lucide="inbox"></i><span>No tasks</span></div><?php else:foreach($list as $t):
$editPayload=['id'=>(int)$t['id'],'title'=>$t['title'],'description'=>$t['description']??'','primary_assignee_id'=>(int)$t['primary_assignee_id'],'category_id'=>(int)$t['category_id'],'priority'=>$t['priority'],'due_at'=>$t['due_at']?date('Y-m-d\TH:i',strtotime($t['due_at'])):'','status'=>$t['status'],'progress'=>(int)$t['progress']];
$viewPayload=['code'=>$t['task_code'],'title'=>$t['title'],'description'=>$t['description']?:'No description added.','assignee'=>$t['assignee']?:'Unassigned','category'=>$t['category']?:'General','priority'=>ucfirst($t['priority']),'status'=>ucwords(str_replace('_',' ',$t['status'])),'status_key'=>$t['status'],'progress'=>(int)$t['progress'],'start'=>$t['start_date']?date('d M Y',strtotime($t['start_date'])):'Not set','due'=>$t['due_at']?format_datetime($t['due_at'],'d M Y, h:i A'):'No due date','completed'=>$t['completed_at']?format_datetime($t['completed_at'],'d M Y, h:i A'):'—'];?>
<article class="task-card" draggable="<?=can('tasks.edit')?'true':'false'?>" data-task-card data-task-id="<?=$t['id']?>" data-task-status="<?=e($t['status'])?>"><div class="task-drag-handle" title="Drag task"><i data-lucide="grip-vertical"></i></div><div class="task-tags"><span class="priority <?=e($t['priority'])?>"><?=e(ucfirst($t['priority']))?></span><small><?=e($t['task_code'])?></small></div><button class="task-card-main" type="button" data-task-view='<?=e(json_encode($viewPayload,JSON_UNESCAPED_SLASHES))?>'><h4><?=e($t['title'])?></h4><?php if(trim((string)($t['description']??''))!==''):?><p><?=e(mb_strimwidth($t['description'],0,115,'…'))?></p><?php endif;?><div class="task-assignee"><span class="avatar tiny"><?=e(strtoupper(substr($t['assignee']??'U',0,1)))?></span><span><?=e($t['assignee']??'Unassigned')?></span></div><div class="task-card-progress"><span><i style="width:<?=e((string)$t['progress'])?>%"></i></span><b><?=number_format((int)$t['progress'])?>%</b></div></button><div class="task-bottom"><span class="<?=($t['due_at']&&strtotime($t['due_at'])<time()&&!in_array($t['status'],['completed','cancelled'],true))?'danger-text':''?>"><i data-lucide="clock-3"></i><?=e($t['due_at']?format_datetime($t['due_at'],'d M, h:i A'):'No deadline')?></span><div class="toolbar-actions"><button class="icon-btn sm" title="View task details" data-task-view='<?=e(json_encode($viewPayload,JSON_UNESCAPED_SLASHES))?>'><i data-lucide="eye"></i></button><?php if(can('tasks.create')):?><button class="icon-btn sm" title="Duplicate task" data-task-duplicate='<?=e(json_encode($editPayload,JSON_UNESCAPED_SLASHES))?>'><i data-lucide="copy-plus"></i></button><?php endif;?><?php if(can('tasks.edit')):?><button class="icon-btn sm" title="Edit task" data-task-edit='<?=e(json_encode($editPayload,JSON_UNESCAPED_SLASHES))?>'><i data-lucide="pencil"></i></button><form method="post" action="<?=e(url('handlers/task-delete.php'))?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=$t['id']?>"><button class="icon-btn sm danger-text" title="Delete task" data-confirm="Delete task <?=e($t['task_code'])?>?"><i data-lucide="trash-2"></i></button></form><?php endif;?></div></div></article>
<?php endforeach;endif;?></div></div><?php endforeach;?></section>

