lect></label><label>Priority<select name="priority" id="taskCreatePriority"><option value="medium">Medium</option><option value="high">High</option><option value="urgent">Urgent</option><option value="low">Low</option></select></label><label>Starting status<select name="status" id="taskCreateStatus"><?php foreach($workflow as $s=>$label):?><option value="<?=$s?>" <?=$s==='to_do'?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></label><label>Due date & time <small class="field-optional">Optional</small><input type="datetime-local" name="due_at" id="taskCreateDue"></label><label class="span-2">Initial progress <span id="taskCreateProgressValue">0%</span><input type="range" name="progress" id="taskCreateProgress" min="0" max="100" step="5" value="0"></label><div class="form-actions span-2"><button type="button" class="btn btn-soft" data-modal-close>Cancel</button><button class="btn btn-primary" id="taskCreateSubmit"><i data-lucide="plus"></i>Create task</button></div></form></div></div>

